import {smoothingNode} from './mesh-smooth-fixtures.mjs';
import {meshSelectionGeometryDigest} from '../../src/mesh-selection-data.js';
export function sculptNode({flat=true,protectedRegion=false}={}){const n=smoothingNode({protectedRegion:false});n.name='Synthetische Pinselplatte';if(flat)for(let i=2;i<n.mesh.verts.length;i+=3)if(n.mesh.verts[i]>3)n.mesh.verts[i]=4;if(protectedRegion){const ids=[];for(let f=0;f<n.mesh.triangles.length/3;f++)if(n.mesh.triangles.slice(f*3,f*3+3).every(v=>n.mesh.verts[v*3]>=5&&n.mesh.verts[v*3+2]>=3))ids.push(f);n.metadata.meshProtection={format:'FormnaroMeshProtection',version:1,regions:[{id:'contact',name:'Anlagefläche',purpose:'contact',geometryDigest:meshSelectionGeometryDigest(n),triangleIds:ids}]};}return n;}
export const sculptOptions=(n,patch={})=>({method:'bounded-brush-v1',geometryDigest:meshSelectionGeometryDigest(n),triangleIds:null,maxDeviation:1,symmetry:null,strokes:[{tool:'inflate',radius:4,strength:.5,points:[[0,0,4]],normal:[0,0,1],delta:[0,0,0]}],...patch});
